query:
mutation siteUpdateWifiRadioProfile ( $accountId:ID! $updateWifiRadioProfileInput:UpdateWifiRadioProfileInput!) {
	site ( accountId:$accountId ) {
		updateWifiRadioProfile ( input:$updateWifiRadioProfileInput  )  {
			wifiRadioProfile {
				id
				site {
					id
					name
				}
				band24 {
					band
					standard
					channelWidth
					dfsEnabled
					channel
				}
				band5 {
					band
					standard
					channelWidth
					dfsEnabled
					channel
				}
			}
		}
	}	
}
